"""Small HTML tree for tests, standard library only.

parse(html) returns a root Element. by_role matches an explicit role
attribute or the implicit role of a few tags, with the accessible name taken
from aria-label or the element's text. by_testid matches data-testid.
"""
from html.parser import HTMLParser

VOID = {"br", "hr", "img", "input", "link", "meta"}
IMPLICIT_ROLES = {"button": "button", "li": "listitem", "nav": "navigation",
                  "ol": "list", "table": "table", "tr": "row", "ul": "list"}


class Element:
    def __init__(self, tag, attrs, parent=None):
        self.tag, self.attrs, self.parent, self.nodes = tag, dict(attrs), parent, []

    @property
    def classes(self):
        return (self.attrs.get("class") or "").split()

    @property
    def children(self):
        return [node for node in self.nodes if isinstance(node, Element)]

    def text(self):
        parts = (node if isinstance(node, str) else node.text() for node in self.nodes)
        return " ".join(" ".join(parts).split())

    def iter(self):
        for child in self.children:
            yield child
            yield from child.iter()

    def find_all(self, predicate):
        return [element for element in self.iter() if predicate(element)]


def role_of(element):
    return element.attrs.get("role") or IMPLICIT_ROLES.get(element.tag)


def by_role(root, role, name=None):
    def matches(element):
        if role_of(element) != role:
            return False
        return name is None or (element.attrs.get("aria-label") or element.text()) == name
    return root.find_all(matches)


def by_testid(root, testid):
    return root.find_all(lambda element: element.attrs.get("data-testid") == testid)


class _Builder(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.root = self.current = Element("#root", {})

    def handle_starttag(self, tag, attrs):
        element = Element(tag, attrs, self.current)
        self.current.nodes.append(element)
        if tag not in VOID:
            self.current = element

    def handle_endtag(self, tag):
        node = self.current
        while node is not self.root and node.tag != tag:
            node = node.parent
        if node is not self.root:
            self.current = node.parent

    def handle_data(self, data):
        self.current.nodes.append(data)


def parse(html):
    builder = _Builder()
    builder.feed(html)
    builder.close()
    return builder.root

